"""${message}

Revision ID: ${up_revision}
Revises: ${down_revision | comma,n}
Create Date: ${create_date}
"""
from alembic import op
import sqlalchemy as sa
${imports if imports else ""}

# revision identifiers
revision = ${repr(up_revision)}
down_revision = ${repr(down_revision)}
branch_labels = ${repr(branch_labels)}
depends_on = ${repr(depends_on)}


def upgrade() -> None:
    ${upgrades if upgrades else "pass"}


def downgrade() -> None:
    ${downgrades if downgrades else "pass"}

{
  "req_id": "REQ-001",
  "lane": "sql",
  "title": "Canonical data contract and migration backbone",
  "commands": [
    {
      "id": "migrate",
      "description": "Apply Alembic migration to test database",
      "command": "cd runs/kit/REQ-001/src && alembic -c data/migrations/alembic.ini upgrade head",
      "env": {
        "DATABASE_URL": "postgresql+psycopg2://postgres:postgres@localhost:5432/docmgmt"
      }
    },
    {
      "id": "seed",
      "description": "Run seed data script",
      "command": "cd runs/kit/REQ-001/src && python -m data.seed",
      "env": {
        "DATABASE_URL": "postgresql+psycopg2://postgres:postgres@localhost:5432/docmgmt"
      }
    },
    {
      "id": "test",
      "description": "Run all REQ-001 behaviour tests",
      "command": "cd runs/kit/REQ-001 && pytest test/ -v --tb=short",
      "env": {}
    },
    {
      "id": "test_with_external_db",
      "description": "Run tests against an external PostgreSQL instance",
      "command": "cd runs/kit/REQ-001 && pytest test/ -v --tb=short",
      "env": {
        "TEST_DATABASE_URL": "postgresql+psycopg2://postgres:postgres@localhost:5432/testdb"
      }
    }
  ],
  "reports": [
    {
      "id": "pytest_output",
      "description": "pytest stdout/stderr with test results",
      "type": "stdout"
    }
  ],
  "gate_policy": {
    "min_coverage_pct": 0,
    "max_criticals": 0,
    "fail_conditions": [
      "Migration fails to apply",
      "Migration is not idempotent (second run errors)",
      "Any canonical table missing after migration",
      "FK constraint not enforced (orphan insert succeeds)",
      "Enum values do not match SPEC (7 Italian values)",
      "pgvector extension not available",
      "Embedding column rejects vector data",
      "audit_log UPDATE or DELETE succeeds",
      "Seed script fails or inserts zero document types",
      "Any table missing created_at or updated_at columns"
    ]
  }
}
